import{_ as s,o as n,c as e,aa as t}from"./chunks/framework.VLjJFeoF.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"docs/interview/net/restful.md","filePath":"docs/interview/net/restful.md","lastUpdated":1770685239000}'),p={name:"docs/interview/net/restful.md"};function l(i,a,r,d,o,c){return n(),e("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1770685239000"},[...a[0]||(a[0]=[t(`<p>RESTful API（Representational State Transfer API）是一种基于 HTTP 的网络接口设计风格，广泛用于网络应用之间的交互。REST 本质上是一组架构原则和约束，而不是具体的标准或协议。一个 Web 服务被称为“RESTful”，意味着它遵循 REST 的设计原则，提供高效、可靠且可扩展的网络服务。</p><p>RESTful 设计强调无状态通信，每个请求都应包含处理该请求所需的所有信息，服务器不应维护客户端的会话状态。此外，RESTful API 采用分层架构，允许系统的不同部分独立扩展和优化。</p><h4 id="_1-uri-设计" tabindex="-1">1. URI 设计<a href="#1-uri-设计"></a> <a class="header-anchor" href="#_1-uri-设计" aria-label="Permalink to &quot;1\\. URI 设计[](#1-uri-设计)&quot;">​</a></h4><p>RESTful API 采用清晰且易读的 URI（统一资源定位符）来表示资源（宾语），而使用 HTTP 方法（如 GET、POST、PUT、DELETE）来表示对资源的操作（动词）。遵循以下最佳实践可以确保 API 的一致性和可维护性。</p><h5 id="_1-1-http-方法与-crud-操作的映射" tabindex="-1">1.1 HTTP 方法与 CRUD 操作的映射<a href="#11-http-方法与-crud-操作的映射"></a> <a class="header-anchor" href="#_1-1-http-方法与-crud-操作的映射" aria-label="Permalink to &quot;1.1 HTTP 方法与 CRUD 操作的映射[](#11-http-方法与-crud-操作的映射)&quot;">​</a></h5><table tabindex="0"><thead><tr><th>HTTP 方法</th><th>操作</th><th>说明</th></tr></thead><tbody><tr><td>GET</td><td>读取（Read）</td><td>获取资源列表或单个资源</td></tr><tr><td>POST</td><td>创建（Create）</td><td>创建新资源</td></tr><tr><td>PUT</td><td>更新（Update）</td><td>进行完整的资源更新</td></tr><tr><td>PATCH</td><td>部分更新（Update）</td><td>更新资源的部分字段</td></tr><tr><td>DELETE</td><td>删除（Delete）</td><td>删除指定的资源</td></tr></tbody></table><p><strong>示例</strong></p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /users           # 获取所有用户</span></span>
<span class="line"><span>GET /users/123       # 获取 ID 为 123 的用户</span></span>
<span class="line"><span>POST /users          # 创建新用户</span></span>
<span class="line"><span>PUT /users/123       # 更新 ID 为 123 的用户信息</span></span>
<span class="line"><span>PATCH /users/123     # 部分更新用户信息</span></span>
<span class="line"><span>DELETE /users/123    # 删除 ID 为 123 的用户</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h5 id="_1-2-url-设计原则" tabindex="-1">1.2 URL 设计原则<a href="#12-url-设计原则"></a> <a class="header-anchor" href="#_1-2-url-设计原则" aria-label="Permalink to &quot;1.2 URL 设计原则[](#12-url-设计原则)&quot;">​</a></h5><h6 id="✅-使用名词表示资源-而非动词" tabindex="-1">✅ 使用名词表示资源，而非动词<a href="#-使用名词表示资源而非动词"></a> <a class="header-anchor" href="#✅-使用名词表示资源-而非动词" aria-label="Permalink to &quot;✅ 使用名词表示资源，而非动词[](#-使用名词表示资源而非动词)&quot;">​</a></h6><p>错误示例：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/getAllUsers</span></span>
<span class="line"><span>/createNewUser</span></span>
<span class="line"><span>/deleteAllOrders</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>正确示例：</p><p>URI 应该专注于资源的表示，而非操作行为。</p><h6 id="✅-使用复数形式表示集合" tabindex="-1">✅ 使用复数形式表示集合<a href="#-使用复数形式表示集合"></a> <a class="header-anchor" href="#✅-使用复数形式表示集合" aria-label="Permalink to &quot;✅ 使用复数形式表示集合[](#-使用复数形式表示集合)&quot;">​</a></h6><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/users       # 表示所有用户</span></span>
<span class="line"><span>/users/123   # 表示某个特定用户</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h6 id="✅-使用嵌套关系表示层级" tabindex="-1">✅ 使用嵌套关系表示层级<a href="#-使用嵌套关系表示层级"></a> <a class="header-anchor" href="#✅-使用嵌套关系表示层级" aria-label="Permalink to &quot;✅ 使用嵌套关系表示层级[](#-使用嵌套关系表示层级)&quot;">​</a></h6><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/users/123/posts       # 获取用户 123 发表的所有文章</span></span>
<span class="line"><span>/posts/456/comments    # 获取文章 456 的所有评论</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h6 id="✅-避免过深的-url-层级" tabindex="-1">✅ 避免过深的 URL 层级<a href="#-避免过深的-url-层级"></a> <a class="header-anchor" href="#✅-避免过深的-url-层级" aria-label="Permalink to &quot;✅ 避免过深的 URL 层级[](#-避免过深的-url-层级)&quot;">​</a></h6><p>❌ 不推荐：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /users/123/orders/456/items/789</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>✅ 推荐：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /orders/456/items/789</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>对于复杂的查询，可以使用查询参数：</p><h4 id="_2-http-状态码" tabindex="-1">2. HTTP 状态码<a href="#2-http-状态码"></a> <a class="header-anchor" href="#_2-http-状态码" aria-label="Permalink to &quot;2\\. HTTP 状态码[](#2-http-状态码)&quot;">​</a></h4><p>RESTful API 通过 HTTP 状态码指示请求结果，正确使用状态码可以减少客户端的解析成本，提高交互的清晰度。</p><h5 id="_2-1-常见状态码" tabindex="-1">2.1 常见状态码<a href="#21-常见状态码"></a> <a class="header-anchor" href="#_2-1-常见状态码" aria-label="Permalink to &quot;2.1 常见状态码[](#21-常见状态码)&quot;">​</a></h5><table tabindex="0"><thead><tr><th>状态码</th><th>含义</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>200 OK</strong></td><td>请求成功</td><td>适用于 <code>GET</code> 请求</td></tr><tr><td><strong>201 Created</strong></td><td>资源创建成功</td><td>适用于 <code>POST</code> 请求，响应头应包含 <code>Location</code> 指向新资源</td></tr><tr><td><strong>204 No Content</strong></td><td>操作成功但无返回内容</td><td>适用于 <code>PUT</code>、<code>PATCH</code> 或 <code>DELETE</code> 请求</td></tr><tr><td><strong>400 Bad Request</strong></td><td>请求格式错误</td><td>客户端提交的数据无效</td></tr><tr><td><strong>401 Unauthorized</strong></td><td>需要身份验证</td><td>客户端未提供身份凭证或凭证无效</td></tr><tr><td><strong>403 Forbidden</strong></td><td>权限不足</td><td>客户端身份验证成功但无权限访问资源</td></tr><tr><td><strong>404 Not Found</strong></td><td>资源不存在</td><td>访问了错误的 URL</td></tr><tr><td><strong>405 Method Not Allowed</strong></td><td>请求方法不被允许</td><td>资源不支持该 HTTP 方法</td></tr><tr><td><strong>409 Conflict</strong></td><td>资源冲突</td><td>适用于并发修改的情况</td></tr><tr><td><strong>429 Too Many Requests</strong></td><td>请求过多</td><td>触发 API 访问速率限制</td></tr><tr><td><strong>500 Internal Server Error</strong></td><td>服务器内部错误</td><td>服务器端出现异常</td></tr></tbody></table><p><strong>示例</strong></p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP/1.1 201 Created</span></span>
<span class="line"><span>Location: /users/123</span></span>
<span class="line"><span>Content-Type: application/json</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;id&quot;: 123,</span></span>
<span class="line"><span>  &quot;name&quot;: &quot;John Doe&quot;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h4 id="_3-服务器响应格式" tabindex="-1">3. 服务器响应格式<a href="#3-服务器响应格式"></a> <a class="header-anchor" href="#_3-服务器响应格式" aria-label="Permalink to &quot;3\\. 服务器响应格式[](#3-服务器响应格式)&quot;">​</a></h4><h5 id="_3-1-统一使用-json-作为返回格式" tabindex="-1">3.1 统一使用 JSON 作为返回格式<a href="#31-统一使用-json-作为返回格式"></a> <a class="header-anchor" href="#_3-1-统一使用-json-作为返回格式" aria-label="Permalink to &quot;3.1 统一使用 JSON 作为返回格式[](#31-统一使用-json-作为返回格式)&quot;">​</a></h5><p>RESTful API 应返回结构化的 JSON 数据，并在响应头中指定：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Content-Type: application/json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>示例</strong></p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;id&quot;: 123,</span></span>
<span class="line"><span>  &quot;name&quot;: &quot;John Doe&quot;,</span></span>
<span class="line"><span>  &quot;email&quot;: &quot;john@example.com&quot;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h5 id="_3-2-发生错误时返回适当的状态码" tabindex="-1">3.2 发生错误时返回适当的状态码<a href="#32-发生错误时返回适当的状态码"></a> <a class="header-anchor" href="#_3-2-发生错误时返回适当的状态码" aria-label="Permalink to &quot;3.2 发生错误时返回适当的状态码[](#32-发生错误时返回适当的状态码)&quot;">​</a></h5><p>错误信息应提供足够的上下文，帮助客户端理解问题。</p><p>❌ 错误示例（不推荐）</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP/1.1 200 OK</span></span>
<span class="line"><span>Content-Type: application/json</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;status&quot;: &quot;failure&quot;,</span></span>
<span class="line"><span>  &quot;error&quot;: &quot;Invalid user ID&quot;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>✅ 推荐：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP/1.1 400 Bad Request</span></span>
<span class="line"><span>Content-Type: application/json</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;error&quot;: &quot;Invalid user ID&quot;,</span></span>
<span class="line"><span>  &quot;detail&quot;: &quot;User ID must be a positive integer&quot;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h5 id="_3-3-api-响应应包含链接-hateoas" tabindex="-1">3.3 API 响应应包含链接（HATEOAS）<a href="#33-api-响应应包含链接hateoas"></a> <a class="header-anchor" href="#_3-3-api-响应应包含链接-hateoas" aria-label="Permalink to &quot;3.3 API 响应应包含链接（HATEOAS）[](#33-api-响应应包含链接hateoas)&quot;">​</a></h5><p>在 RESTful 设计中，返回的 JSON 结构可以包含指向相关资源的链接。</p><p><strong>示例</strong></p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;id&quot;: 123,</span></span>
<span class="line"><span>  &quot;name&quot;: &quot;John Doe&quot;,</span></span>
<span class="line"><span>  &quot;_links&quot;: {</span></span>
<span class="line"><span>    &quot;self&quot;: { &quot;href&quot;: &quot;/users/123&quot; },</span></span>
<span class="line"><span>    &quot;orders&quot;: { &quot;href&quot;: &quot;/users/123/orders&quot; }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h4 id="_4-api-设计最佳实践" tabindex="-1">4. API 设计最佳实践<a href="#4-api-设计最佳实践"></a> <a class="header-anchor" href="#_4-api-设计最佳实践" aria-label="Permalink to &quot;4\\. API 设计最佳实践[](#4-api-设计最佳实践)&quot;">​</a></h4><h5 id="✅-4-1-一致性" tabindex="-1">✅ 4.1 一致性<a href="#-41-一致性"></a> <a class="header-anchor" href="#✅-4-1-一致性" aria-label="Permalink to &quot;✅ 4.1 一致性[](#-41-一致性)&quot;">​</a></h5><p>所有资源的 URL 结构应保持一致，避免混用不同的风格。例如，不要在同一 API 中既使用 <code>/user</code> 又使用 <code>/users</code>。</p><h5 id="✅-4-2-采用分页机制" tabindex="-1">✅ 4.2 采用分页机制<a href="#-42-采用分页机制"></a> <a class="header-anchor" href="#✅-4-2-采用分页机制" aria-label="Permalink to &quot;✅ 4.2 采用分页机制[](#-42-采用分页机制)&quot;">​</a></h5><p>对于返回大量数据的请求，应提供分页参数：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /users?page=2&amp;limit=20</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>标准响应格式：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;total&quot;: 100,</span></span>
<span class="line"><span>  &quot;page&quot;: 2,</span></span>
<span class="line"><span>  &quot;limit&quot;: 20,</span></span>
<span class="line"><span>  &quot;data&quot;: [</span></span>
<span class="line"><span>    { &quot;id&quot;: 21, &quot;name&quot;: &quot;Alice&quot; },</span></span>
<span class="line"><span>    { &quot;id&quot;: 22, &quot;name&quot;: &quot;Bob&quot; }</span></span>
<span class="line"><span>  ]</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h5 id="✅-4-3-允许跨域访问-cors" tabindex="-1">✅ 4.3 允许跨域访问（CORS）<a href="#-43-允许跨域访问cors"></a> <a class="header-anchor" href="#✅-4-3-允许跨域访问-cors" aria-label="Permalink to &quot;✅ 4.3 允许跨域访问（CORS）[](#-43-允许跨域访问cors)&quot;">​</a></h5><p>如果 API 需要支持跨域请求，应在响应头中添加：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Access-Control-Allow-Origin: *</span></span>
<span class="line"><span>Access-Control-Allow-Methods: GET, POST, PUT, DELETE</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h5 id="✅-4-4-避免暴露敏感信息" tabindex="-1">✅ 4.4 避免暴露敏感信息<a href="#-44-避免暴露敏感信息"></a> <a class="header-anchor" href="#✅-4-4-避免暴露敏感信息" aria-label="Permalink to &quot;✅ 4.4 避免暴露敏感信息[](#-44-避免暴露敏感信息)&quot;">​</a></h5><ul><li>API 响应不应包含数据库 ID 或密码哈希。</li><li>仅返回客户端所需的字段，避免返回不必要的数据。</li></ul><h5 id="✅-4-5-采用版本控制" tabindex="-1">✅ 4.5 采用版本控制<a href="#-45-采用版本控制"></a> <a class="header-anchor" href="#✅-4-5-采用版本控制" aria-label="Permalink to &quot;✅ 4.5 采用版本控制[](#-45-采用版本控制)&quot;">​</a></h5><p>避免在 URL 级别硬编码版本号，如 <code>/v1/users</code>，推荐使用 HTTP 头：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Accept: application/vnd.myapi.v1+json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h4 id="_5-结论" tabindex="-1">5. 结论<a href="#5-结论"></a> <a class="header-anchor" href="#_5-结论" aria-label="Permalink to &quot;5\\. 结论[](#5-结论)&quot;">​</a></h4><p>RESTful API 设计强调资源的表述、无状态交互和标准化 HTTP 方法。通过遵循一致的 URL 规则、合理使用状态码、提供结构化的 JSON 响应、优化性能（如分页、缓存）以及实现安全性控制（如身份验证和 CORS），我们可以构建一个高效、易扩展、可维护的 API。</p><p>RESTful 设计不仅使 API 更具可读性，也提升了开发和使用的便捷性。良好的 API 设计是构建现代 Web 应用程序的关键。</p>`,65)])])}const h=s(p,[["render",l]]);export{b as __pageData,h as default};
